insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('placinte-cu-branza', '🥟', 50, 6, 'Plăcinte cu brânză', 'Плацинды с брынзой', 'Plăcinte with cheese', 'Frământă un aluat moale din 500 g făină, un pahar de chefir sau lapte, un ou și puțină sare. Lasă-l 15 minute.
Amestecă brânza cu un ou și mărar tocat.
Împarte aluatul în 6 bile, întinde fiecare subțire, pune umplutura la mijloc și strânge marginile.
Turtește ușor plăcintele și coace-le în tigaie cu puțin ulei, câte 3–4 minute pe fiecare parte, sau 20 de minute în cuptor la 200 °C.', 'Замеси мягкое тесто из 500 г муки, стакана кефира или молока, одного яйца и щепотки соли. Оставь на 15 минут.
Смешай брынзу с яйцом и рубленым укропом.
Раздели тесто на 6 шариков, раскатай каждый тонко, выложи начинку в центр и защипни края.
Слегка прижми плацинды и жарь на сковороде с небольшим количеством масла по 3–4 минуты с каждой стороны или выпекай 20 минут в духовке при 200 °C.', 'Knead a soft dough from 500 g flour, a glass of kefir or milk, one egg and a pinch of salt. Rest it for 15 minutes.
Mix the brânză with an egg and chopped dill.
Divide the dough into 6 balls, roll each one thin, put filling in the middle and pinch the edges together.
Flatten the pies a little and fry them in a pan with a little oil, 3–4 minutes per side, or bake 20 minutes at 200 °C.', 'Frigo starter recipe (AI draft) — check before the competition')
