insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('coltunasi-cu-branza', '🥟', 45, 4, 'Colțunași cu brânză', 'Колцунаши с брынзой', 'Colțunași (cheese dumplings)', 'Fă un aluat tare din 400 g făină, un ou, apă călduță și sare. Lasă-l acoperit 20 de minute.
Amestecă brânza cu un ou.
Întinde aluatul subțire, taie cercuri cu un pahar, pune o linguriță de brânză și lipește marginile.
Fierbe colțunașii în apă cu sare până ies la suprafață, apoi încă 2 minute. Servește cu smântână.', 'Замеси крутое тесто из 400 г муки, яйца, тёплой воды и соли. Оставь под крышкой на 20 минут.
Смешай брынзу с яйцом.
Тонко раскатай тесто, вырежи кружки стаканом, положи ложечку брынзы и залепи края.
Вари колцунаши в подсоленной воде, пока не всплывут, и ещё 2 минуты. Подавай со сметаной.', 'Make a firm dough from 400 g flour, an egg, warm water and salt. Cover and rest 20 minutes.
Mix the brânză with an egg.
Roll the dough thin, cut circles with a glass, add a teaspoon of cheese and seal the edges.
Boil in salted water until they float, then 2 minutes more. Serve with sour cream.', 'Frigo starter recipe (AI draft) — check before the competition')
