insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('sarmale', '🥬', 120, 8, 'Sarmale în foi de varză', 'Голубцы (сармале)', 'Sarmale (cabbage rolls)', 'Opărește frunzele de varză ca să se înmoaie și scoate-le cotorul gros.
Amestecă carnea tocată cu orezul spălat, ceapa tocată și călită, sare și piper.
Pune câte o lingură de umplutură pe fiecare frunză și rulează strâns.
Așază sarmalele în oală, toarnă suc de roșii și apă cât să le acopere și fierbe la foc mic cam 1 oră și jumătate.', 'Ошпарь капустные листья, чтобы они стали мягкими, и срежь толстые прожилки.
Смешай фарш с промытым рисом, мелко нарезанным обжаренным луком, солью и перцем.
Положи по ложке начинки на каждый лист и плотно сверни.
Уложи голубцы в кастрюлю, залей томатным соком и водой, чтобы покрыть, и туши на слабом огне около полутора часов.', 'Blanch the cabbage leaves until soft and trim off the thick stem.
Mix the minced meat with washed rice, chopped fried onion, salt and pepper.
Put a spoon of filling on each leaf and roll it up tightly.
Pack the rolls in a pot, cover with tomato juice and water and simmer gently for about 1½ hours.', 'Frigo starter recipe (AI draft) — check before the competition')
