insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('omleta-cu-legume', '🍳', 15, 2, 'Omletă cu legume', 'Омлет с овощами', 'Vegetable omelette', 'Taie mărunt legumele pe care le ai și călește-le 3 minute în tigaie.
Bate 3–4 ouă cu un strop de lapte, sare și piper.
Toarnă ouăle peste legume și ține la foc mic până se încheagă.
Presară brânză rasă și servește cald.', 'Мелко нарежь овощи, какие есть, и обжарь их 3 минуты на сковороде.
Взбей 3–4 яйца с каплей молока, солью и перцем.
Вылей яйца на овощи и держи на слабом огне, пока омлет не схватится.
Посыпь тёртым сыром и подавай горячим.', 'Chop whatever vegetables you have and fry them for 3 minutes.
Beat 3–4 eggs with a splash of milk, salt and pepper.
Pour the eggs over the vegetables and keep on low heat until set.
Sprinkle with grated cheese and serve warm.', 'Frigo starter recipe (AI draft) — check before the competition')
