insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('salata-de-vara', '🥗', 10, 3, 'Salată de roșii și castraveți', 'Салат из помидоров и огурцов', 'Tomato and cucumber salad', 'Taie roșiile și castraveții felii, iar ceapa rondele subțiri.
Pune sare, ulei de floarea-soarelui și un strop de oțet.
Amestecă ușor și presară brânză sfărâmată deasupra.', 'Нарежь помидоры и огурцы дольками, а лук — тонкими кольцами.
Посоли, полей подсолнечным маслом и каплей уксуса.
Аккуратно перемешай и сверху раскроши брынзу.', 'Slice the tomatoes and cucumbers, and the onion into thin rings.
Add salt, sunflower oil and a drop of vinegar.
Toss gently and crumble brânză on top.', 'Frigo starter recipe (AI draft) — check before the competition')
