insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('friganele', '🍞', 15, 2, 'Frigănele din pâine veche', 'Гренки из чёрствого хлеба', 'Frigănele (French toast from old bread)', 'Bate 2 ouă cu 100 ml lapte și un praf de sare (sau zahăr, pentru varianta dulce).
Înmoaie feliile de pâine în amestec pe ambele părți.
Prăjește-le în tigaie cu puțin ulei sau unt până se rumenesc.
Servește-le cu smântână, brânză sau gem. Bun mod de a salva pâinea de ieri!', 'Взбей 2 яйца со 100 мл молока и щепоткой соли (или сахара — для сладкого варианта).
Обмакни ломтики хлеба в смесь с обеих сторон.
Обжарь их на сковороде с небольшим количеством масла до румяности.
Подавай со сметаной, брынзой или вареньем. Хороший способ спасти вчерашний хлеб!', 'Beat 2 eggs with 100 ml milk and a pinch of salt (or sugar, for a sweet version).
Dip the bread slices in the mix on both sides.
Fry in a pan with a little oil or butter until golden.
Serve with sour cream, cheese or jam. A good way to save yesterday''s bread!', 'Frigo starter recipe (AI draft) — check before the competition')
