insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('ardei-umpluti', '🫑', 80, 5, 'Ardei umpluți', 'Фаршированные перцы', 'Stuffed peppers', 'Taie capacul ardeilor și scoate semințele.
Amestecă carnea cu orezul spălat, morcovul ras, ceapă călită, sare și piper.
Umple ardeii fără să-i îndesi, ca orezul să aibă loc să crească.
Așază-i în oală, acoperă-i cu apă și suc de roșii și fierbe-i la foc mic 50–60 de minute. Servește cu smântână.', 'Срежь у перцев верхушки и удали семена.
Смешай фарш с промытым рисом, тёртой морковью, обжаренным луком, солью и перцем.
Начини перцы, не утрамбовывая, чтобы рису было куда набухать.
Уложи их в кастрюлю, залей водой с томатным соком и туши на слабом огне 50–60 минут. Подавай со сметаной.', 'Cut the tops off the peppers and remove the seeds.
Mix the meat with washed rice, grated carrot, fried onion, salt and pepper.
Fill the peppers loosely so the rice has room to swell.
Stand them in a pot, cover with water and tomato juice and simmer 50–60 minutes. Serve with sour cream.', 'Frigo starter recipe (AI draft) — check before the competition')
