insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('mere-coapte', '🍎', 35, 4, 'Mere coapte cu nucă și miere', 'Печёные яблоки с орехами и мёдом', 'Baked apples with walnuts and honey', 'Scoate cotorul merelor cu un cuțit mic, fără să le tai până jos.
Umple golul cu nucă mărunțită, miere și puțină scorțișoară.
Coace-le 25–30 de minute la 180 °C, până se înmoaie.
Servește-le calde, cu iaurt sau brânză dulce. Merg perfect merele puțin zbârcite!', 'Вырежи сердцевину яблок маленьким ножом, не прорезая до дна.
Наполни углубление рублеными орехами, мёдом и щепоткой корицы.
Запекай 25–30 минут при 180 °C, пока яблоки не станут мягкими.
Подавай тёплыми с йогуртом или творогом. Отлично подходят слегка сморщенные яблоки!', 'Core the apples with a small knife without cutting through the bottom.
Fill the hole with chopped walnuts, honey and a little cinnamon.
Bake 25–30 minutes at 180 °C until soft.
Serve warm with yogurt or sweet cheese. Slightly wrinkly apples work perfectly!', 'Frigo starter recipe (AI draft) — check before the competition')
