insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('compot-de-fructe', '🫙', 25, 8, 'Compot de fructe', 'Фруктовый компот', 'Fruit compot', 'Spală fructele care încep să se înmoaie și taie-le bucăți, fără sâmburi.
Pune-le într-o oală cu 2–3 litri de apă și zahăr după gust.
Fierbe 10–15 minute de la clocot.
Lasă compotul să se răcească și păstrează-l la frigider până la 3 zile.', 'Вымой фрукты, которые начинают размягчаться, и нарежь их кусочками без косточек.
Положи их в кастрюлю с 2–3 литрами воды и сахаром по вкусу.
Вари 10–15 минут после закипания.
Дай компоту остыть и храни в холодильнике до 3 дней.', 'Wash fruit that is getting soft and cut it into pieces without stones.
Put it in a pot with 2–3 litres of water and sugar to taste.
Boil for 10–15 minutes.
Let it cool and keep it in the fridge for up to 3 days.', 'Frigo starter recipe (AI draft) — check before the competition')
