insert into public.recipes (slug, emoji, minutes, servings, title_ro, title_ru, title_en, steps_ro, steps_ru, steps_en, source_note)
values ('cartofi-cu-ceapa', '🥔', 30, 3, 'Cartofi prăjiți cu ceapă și mărar', 'Жареная картошка с луком и укропом', 'Fried potatoes with onion and dill', 'Taie cartofii felii sau bețișoare și usucă-i cu un prosop.
Prăjește-i în ulei încins 15 minute, întorcându-i rar.
Adaugă ceapa tăiată și, dacă ai, resturi de carne sau cârnați, și mai lasă 5 minute.
Sărează la final și presară mărar.', 'Нарежь картофель ломтиками или брусочками и обсуши полотенцем.
Жарь в разогретом масле 15 минут, редко переворачивая.
Добавь нарезанный лук и, если есть, остатки мяса или колбасы и жарь ещё 5 минут.
Посоли в конце и посыпь укропом.', 'Cut the potatoes into slices or sticks and pat them dry.
Fry in hot oil for 15 minutes, turning them rarely.
Add the sliced onion and any leftover meat or sausage and cook 5 more minutes.
Salt at the end and sprinkle with dill.', 'Frigo starter recipe (AI draft) — check before the competition')
